from Crypto.Util.number import *
from libnum import *
from gmpy2 import *

flag = b'******'

e = 65536

p = getPrime(512)
q = getPrime(512)


n = p*q
m = bytes_to_long(flag)

hint = pow((e*p + e**2), q , n)
c = pow(m, e, n)

print("hint=", hint)
print("c=", c)
print("n=", n)
print("p=", p)
print("q=", q)

